javascript:var celkove = Number(tag('zakladne_udaje.celkove_vydavky')) || 0;
var dotacia = Number(tag('zakladne_udaje.pozadovana_dotacia')) || 0;
if (!celkove || !dotacia) { return true; }
var spolu = celkove - dotacia;
if (spolu < 0) { return 'Požadovaná výška dotácie nemôže byť vyššia ako celkové oprávnené výdavky projektu.'; }
if (dotacia < 50000) { return 'Požadovaná výška dotácie je nižšia ako minimálna výška dotácie 50 000 €.'; }
if (dotacia > 300000) { return 'Požadovaná výška dotácie presahuje maximálnu výšku dotácie 300 000 €.'; }
if (dotacia / celkove > 0.9) { return 'Podiel dotácie presahuje 90 % celkových oprávnených výdavkov (spolufinancovanie žiadateľa musí byť najmenej 10 %).'; }
return true;

